def normalize_language(value) -> str:
    """Accept the supported saved codes; malformed values fall back to English."""
    if isinstance(value, str):
        value = value.strip().lower()
        if value in LANGUAGES:
            return value
    return "en"


def translate(message: str, language="en", **values) -> str:
    """Translate an English literal, then format only when values were supplied."""
    text = HU.get(message, message) if normalize_language(language) == "hu" else message
    return text.format(**values) if values else text
